result.text:
      closeModal();
      toast("Todo borrado. Empiezas de cero.");
      render();
      return;
    }
    case "seed-demo": {
      const ok = await confirmDialog({
        title: "Cargar datos de ejemplo",
        message: "Se añadirán 5 proveedores inventados y 11 facturas para que veas cómo funciona. Podrás borrarlo todo después.",
        confirm: "Sí, cargar el ejemplo",
      });
      if (!ok) return;
      seedDemo();
      toast("Datos de ejemplo cargados.");
      render();
      return;
    }
    case "retry-job": {
      const job = ui.jobs.find((j) => j.id === id);
      if (job) {
        job.state = "queued";
        job.pct = 0;
        job.error = "";
        paintIngest();
        runQueue();
      }
      return;
    }
    case "acc-tab": {
      ui.conta.tab = id || "diario";
      render();
      return;
    }
    case "acc-all": {
      ui.conta.range = "all";
      ui.conta.from = "";
      ui.conta.to = "";
      render();
      return;
    }
    case "acc-apertura":
    case "acc-settings": {
      accAperturaModal();
      return;
    }
    case "acc-save-apertura": {
      saveApertura();
      return;
    }
    case "export-acc-csv": {
      exportAccCsv();
      return;
    }
    default:
      return;
  }
}

